    const queue = [start];
    visited[start] = true;
    let head = 0;

    while (head < queue.length) {
        const node = queue[head++];
        process.stdout.write(node + " ");

        for (const next of graph[node]) {
            if (!visited[next]) {
                visited[next] = true;
                queue.push(next);
            }
